package persistence

import (
	"context"
	"database/sql"
	"errors"

	"maple-go-server/internal/domain"
)

// AwardCombat makes a spawn's final-hit experience durable and idempotent.
// The operation identity is generated by the world, never supplied by clients.
func (s *Store) AwardCombat(ctx context.Context, session domain.CharacterSession, operationID string, experience int64) (domain.Character, error) {
	return s.awardCombat(ctx, session, operationID, experience, 0)
}

// AwardCombatKill commits experience and all active quest kill counters together.
// The spawn operation ID is server-generated; it credits one final hitter once.
func (s *Store) AwardCombatKill(ctx context.Context, session domain.CharacterSession, operationID string, experience int64, mobID int) (domain.Character, error) {
	if mobID < 1 {
		return domain.Character{}, domain.ErrInvalidInput
	}
	return s.awardCombat(ctx, session, operationID, experience, mobID)
}
func (s *Store) AwardCombatKillAt(ctx context.Context, session domain.CharacterSession, operationID string, experience int64, mobID, x, y int) (domain.Character, error) {
	if mobID < 1 {
		return domain.Character{}, domain.ErrInvalidInput
	}
	return s.awardCombatAt(ctx, session, operationID, experience, mobID, x, y)
}
func (s *Store) awardCombat(ctx context.Context, session domain.CharacterSession, operationID string, experience int64, mobID int) (domain.Character, error) {
	return s.awardCombatAt(ctx, session, operationID, experience, mobID, session.Character.X, session.Character.Y)
}
func (s *Store) awardCombatAt(ctx context.Context, session domain.CharacterSession, operationID string, experience int64, mobID, x, y int) (domain.Character, error) {
	if len(operationID) < 16 || len(operationID) > 200 || experience < 0 || experience > domain.MaxExperience() {
		return domain.Character{}, domain.ErrInvalidInput
	}
	if session.CharacterID <= 0 || session.AccountID <= 0 || session.Character.ID != session.CharacterID {
		return domain.Character{}, domain.ErrForbidden
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return domain.Character{}, err
	}
	defer tx.Rollback()
	if err = guardLease(ctx, tx, session.Lease); err != nil {
		return domain.Character{}, err
	}
	var generation int64
	err = tx.QueryRowContext(ctx, `SELECT generation FROM ops_account_sessions WHERE account_id=$1 AND session_id=$2 AND generation=$3 AND state='world' AND owner_instance=$4 AND world_epoch=$5 FOR SHARE`, session.AccountID, session.SessionID, session.Generation, session.Lease.InstanceID, session.Lease.Epoch).Scan(&generation)
	if errors.Is(err, sql.ErrNoRows) {
		return domain.Character{}, domain.ErrStaleOwner
	}
	if err != nil {
		return domain.Character{}, err
	}
	err = tx.QueryRowContext(ctx, `SELECT generation FROM ops_character_ownership WHERE character_id=$1 AND account_id=$2 AND session_id=$3 AND generation=$4 AND instance_id=$5 AND epoch=$6 FOR SHARE`, session.CharacterID, session.AccountID, session.SessionID, session.Generation, session.Lease.InstanceID, session.Lease.Epoch).Scan(&generation)
	if errors.Is(err, sql.ErrNoRows) {
		return domain.Character{}, domain.ErrStaleOwner
	}
	if err != nil {
		return domain.Character{}, err
	}
	var id int64
	if err = tx.QueryRowContext(ctx, `SELECT id FROM game_characters WHERE id=$1 FOR UPDATE`, session.CharacterID).Scan(&id); err != nil {
		return domain.Character{}, err
	}
	value, err := readCharacterSQL(ctx, tx, session.CharacterID)
	if err != nil {
		return domain.Character{}, err
	}
	if value.AccountID != session.AccountID || value.WorldID != session.Lease.WorldID {
		return domain.Character{}, domain.ErrForbidden
	}
	if err = rejectPartyCombatCompatibility(ctx, tx, value.ID); err != nil {
		return domain.Character{}, err
	}
	var priorID, priorEXP int64
	err = tx.QueryRowContext(ctx, `SELECT character_id,experience FROM asset_combat_rewards WHERE operation_id=$1`, operationID).Scan(&priorID, &priorEXP)
	if err == nil {
		if priorID != value.ID || priorEXP != experience {
			return domain.Character{}, domain.ErrForbidden
		}
		if mobID > 0 {
			var priorMob int
			if e := tx.QueryRowContext(ctx, `SELECT mob_id FROM game_quest_kill_receipts WHERE character_id=$1 AND operation_id=$2`, value.ID, operationID).Scan(&priorMob); e != nil || priorMob != mobID {
				return domain.Character{}, domain.ErrForbidden
			}
		}
		return value, nil
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return domain.Character{}, err
	}
	if value.Revision != session.Character.Revision {
		return domain.Character{}, domain.ErrStaleOwner
	}
	if value.Job != 0 && value.Job != 100 || value.HP <= 0 || experience > domain.MaxExperience()-value.EXP {
		return domain.Character{}, domain.ErrInvalidInput
	}
	if session.Character.HP <= 0 || session.Character.HP > value.MaxHP || session.Character.MP < 0 || session.Character.MP > value.MaxMP {
		return domain.Character{}, domain.ErrInvalidInput
	}
	// Do not erase damage or MP consumption that the world has not checkpointed
	// yet. The current character revision authorizes the detached live values.
	value.HP = session.Character.HP
	value.MP = session.Character.MP
	if err = applyQuestExperience(&value, experience, operationID); err != nil {
		return domain.Character{}, err
	}
	value.Revision++
	if mobID > 0 {
		if err = recordQuestKill(ctx, tx, &value, operationID, mobID); err != nil {
			return domain.Character{}, err
		}
	}
	if _, err = tx.ExecContext(ctx, `UPDATE game_characters SET exp=$1,level=$2,max_hp=$3,max_mp=$4,hp=$5,mp=$6,str=$7,ap=$8,revision=$9,sp=$10 WHERE id=$11`, value.EXP, value.Level, value.MaxHP, value.MaxMP, value.HP, value.MP, value.STR, value.AP, value.Revision, value.SP, value.ID); err != nil {
		return domain.Character{}, err
	}
	if err = persistBaseVitals(ctx, tx, value); err != nil {
		return domain.Character{}, err
	}
	if _, err = tx.ExecContext(ctx, `INSERT INTO asset_combat_rewards(operation_id,character_id,experience,character_revision) VALUES($1,$2,$3,$4)`, operationID, value.ID, experience, value.Revision); err != nil {
		return domain.Character{}, err
	}
	if mobID > 0 {
		if err = enqueueCombatLootTx(ctx, tx, session, value, operationID, mobID, x, y); err != nil {
			return domain.Character{}, err
		}
	}
	raw, err := marshalRoster(value)
	if err != nil {
		return domain.Character{}, err
	}
	if _, err = tx.ExecContext(ctx, `UPDATE game_character_roster SET snapshot=$1,revision=$2 WHERE character_id=$3`, raw, value.Revision, value.ID); err != nil {
		return domain.Character{}, err
	}
	if _, err = tx.ExecContext(ctx, `INSERT INTO ops_outbox(event_type,account_id,world_id) VALUES('roster.invalidate',$1,$2)`, value.AccountID, value.WorldID); err != nil {
		return domain.Character{}, err
	}
	if err = tx.Commit(); err != nil {
		return domain.Character{}, err
	}
	s.roster.Invalidate(ctx, value.AccountID, value.WorldID)
	return value, nil
}
